const photo=(id)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=900&q=80`;
const races=[
{id:'utmb',name:'UTMB Mont-Blanc',place:'Chamonix · France, Italy & Switzerland',region:'Europe',km:174,difficulty:'Extreme',terrain:'Alpine',temp:14,range:'5–20',date:'2026-08-28',dateNote:'Past edition · next date not confirmed here',url:'https://montblanc.utmb.world/races/utmb',image:'photo-1464822759023-fed622ff2c3b',desc:'A high mountain journey around Mont Blanc, crossing three countries. Prepare for long climbs, technical descents and changing mountain conditions.'},
{id:'cape',name:'Ultra-Trail Cape Town',place:'Cape Town · South Africa',region:'Africa',km:100,difficulty:'Demanding',terrain:'Mountain',temp:25,range:'10–30+',date:'2026-11-21',url:'https://www.ultratrailcapetown.com/ut100',image:'photo-1516026672322-bc52d61a55d5',desc:'Explore the trails of the Cape Peninsula. Rocky climbing and exposed mountain terrain make strength and careful pacing essential.'},
{id:'tarawera',name:'Tarawera T102',place:'Rotorua · New Zealand',region:'Oceania',km:102,difficulty:'Challenging',terrain:'Forest',temp:22,range:'15–25',date:'2027-02-13',url:'https://tarawera.utmb.world/races/t-102',image:'photo-1448375240586-882707db888b',desc:'A lake and forest journey through Rotorua’s native bush and redwoods. Build endurance on rolling trails and practise your race nutrition.'},
{id:'western',name:'Western States 100',place:'California · United States',region:'North America',km:161,difficulty:'Extreme',terrain:'Mountain',temp:30,range:'15–35+',date:'2027-06-26',url:'https://www.wser.org/',image:'photo-1472396961693-142e6e269027',desc:'The iconic 100-mile trail race from Olympic Valley to Auburn. Long descents and hot canyons demand durable legs and heat preparation.'},
{id:'elephant',name:'Chiang Mai · Elephant 100',place:'Chiang Mai · Thailand',region:'Asia',km:100,difficulty:'Demanding',terrain:'Forest',temp:26,range:'15–30',date:'2026-12-04',url:'https://chiangmai.utmb.world/races/ELEPHANT100',image:'photo-1511497584788-876760111969',desc:'A point-to-point route through forests and villages with 5,500 metres of ascent. Prepare for steep climbing, humidity and night running.'},
{id:'uta',name:'Ultra-Trail Australia 100',place:'Blue Mountains · Australia',region:'Oceania',km:100,difficulty:'Demanding',terrain:'Mountain',temp:13,range:'5–18',date:'2027-05-13',dateNote:'Festival starts 13 May · race day within 13–16 May; confirm with organiser',url:'https://uta.utmb.world/races/uta100',image:'photo-1464278533981-50106e6176b1',desc:'A Blue Mountains trail challenge with sustained climbs and stairs. Listed distance is nominal; course details may change for the 2027 edition.'},
{id:'paraty',name:'Paraty Brazil · PTR 108',place:'Paraty · Brazil',region:'South America',km:101,difficulty:'Demanding',terrain:'Forest',temp:27,range:'18–30',date:'2027-09-24',url:'https://paraty.utmb.world/races/ptr108',image:'photo-1441974231531-c6227db76b6e',desc:'A 101 km course through the Atlantic Forest and Serra do Mar with 4,850 metres of climbing. Prepare for humid trails and sustained ascending.'}
];
const $=id=>document.getElementById(id);let view='cards',savedOnly=false;let saved=[];try{saved=JSON.parse(localStorage.getItem('ultraSaved')||'[]');if(!Array.isArray(saved))saved=[]}catch{};
const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
for(const key of ['region','terrain'])[...new Set(races.map(r=>r[key]))].sort().forEach(v=>$(key).add(new Option(v,v)));
races.forEach(r=>$('raceGoal').add(new Option(r.name,r.id)));$('raceGoal').value='tarawera';
const filters=['search','region','distance','difficulty','terrain','temperature','date','group'];filters.forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));
function list(){const q=$('search').value.toLowerCase().trim();return races.filter(r=>(!savedOnly||saved.includes(r.id))&&(!q||(r.name+' '+r.place).toLowerCase().includes(q))&&(!$('region').value||r.region===$('region').value)&&(!$('difficulty').value||r.difficulty===$('difficulty').value)&&(!$('terrain').value||r.terrain===$('terrain').value)&&(!$('distance').value||($('distance').value==='short'?r.km<100:$('distance').value==='medium'?r.km>=100&&r.km<160:r.km>=160))&&(!$('temperature').value||($('temperature').value==='cool'?r.temp<15:$('temperature').value==='mild'?r.temp>=15&&r.temp<25:r.temp>=25))&&(!$('date').value||($('date').value==='upcoming'?r.date>=new Date().toISOString().slice(0,10):r.date.startsWith($('date').value))));}
function card(r){return `<article class="card"><div class="card-photo"><img src="${photo(r.image)}" alt="Illustrative ${r.terrain.toLowerCase()} landscape" loading="lazy"><button class="save ${saved.includes(r.id)?'saved-active':''}" data-save="${r.id}" aria-label="${saved.includes(r.id)?'Unsave':'Save'} ${r.name}">${saved.includes(r.id)?'♥':'♡'}</button><span class="badge">${r.difficulty.toUpperCase()}</span></div><div class="card-body"><div class="location">${r.place}</div><h3>${r.name}</h3><div class="metrics"><div>${r.km} km<span>DISTANCE</span></div><div>${r.terrain}<span>TERRAIN</span></div><div>${r.range}°C<span>EST. CLIMATE</span></div></div><div class="card-bottom"><span>${fmt(r.date)}${r.id==='uta'?' · festival':''}</span><button data-detail="${r.id}">Discover ↗</button></div></div></article>`}
function key(r,g){return g==='km'?r.km<100?'50–99 km':r.km<160?'100–159 km':'160+ km':g==='temp'?r.temp<15?'Cool · under 15°C':r.temp<25?'Mild · 15–24°C':'Hot · 25°C+':g==='date'?new Date(r.date+'T12:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'}):r[g]}
function render(){let rows=list();$('count').textContent=rows.length;$('savedCount').textContent=saved.length;$('savedBtn').classList.toggle('saved-active',savedOnly);const g=$('group').value;
if(!rows.length){$('results').innerHTML='<div class="empty"><h3>No races match your search.</h3><p>Try another filter or clear your selection.</p></div>';return}
if(view==='timeline'){$('results').innerHTML='<div class="timeline">'+rows.sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`<article class="timeline-row"><time>${fmt(r.date)}</time><div><div class="location">${r.place}</div><h3>${r.name}</h3><small>${r.km} km · ${r.difficulty}${r.id==='uta'?' · festival start':''}${r.date<new Date().toISOString().slice(0,10)?' · past edition':''}</small></div><button data-detail="${r.id}">View ↗</button></article>`).join('')+'</div>'}
else if(view==='insights'){const group=g==='none'?'region':g;const groups={};rows.forEach(r=>{const k=key(r,group);groups[k]=(groups[k]||0)+1});$('results').innerHTML=`<h3>Races by ${group==='temp'?'temperature':group==='km'?'distance':group==='region'?'location':group}</h3>`+Object.entries(groups).map(([k,n])=>`<div class="insight-row"><span>${k}</span><div class="bar" style="width:${n/rows.length*60}%"></div><strong>${n}</strong></div>`).join('')}
else if(g==='none')$('results').innerHTML='<div class="cards">'+rows.map(card).join('')+'</div>';else{const groups={};rows.forEach(r=>(groups[key(r,g)]??=[]).push(r));$('results').innerHTML=Object.entries(groups).map(([k,rs])=>`<h3 class="group-title">${k}</h3><div class="cards">${rs.map(card).join('')}</div>`).join('')}
}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));render()});
$('reset').onclick=()=>{filters.forEach(id=>$(id).value=id==='group'?'none':'');savedOnly=false;render()};$('savedBtn').onclick=()=>{savedOnly=!savedOnly;render();$('explore').scrollIntoView()};
$('results').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.save){const id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('ultraSaved',JSON.stringify(saved))}catch{}render()}if(b.dataset.detail)detail(b.dataset.detail)};
function detail(id){const r=races.find(r=>r.id===id);$('detailContent').innerHTML=`<p class="eyebrow">${r.region.toUpperCase()} / ${r.terrain.toUpperCase()}</p><h2>${r.name}</h2><p>${r.place}</p><p>${r.desc}</p><p><strong>${r.km} km · ${r.difficulty} · ${fmt(r.date)}</strong><br>${r.dateNote||'Race start date published by organiser.'}</p><p>Estimated daytime planning range: ${r.range}°C. Conditions can differ substantially, especially at altitude or overnight.</p><a class="source" href="${r.url}" target="_blank" rel="noopener">Official race information ↗</a><br><button class="primary" id="trainRace">Plan for this race ↗</button>`;$('trainRace').onclick=()=>{$('raceGoal').value=id;$('detail').close();$('training').scrollIntoView();};$('detail').showModal()};$('close').onclick=()=>$('detail').close();$('detail').onclick=e=>{if(e.target===$('detail'))$('detail').close()};
$('profileForm').onsubmit=e=>{e.preventDefault();const r=races.find(r=>r.id===$('raceGoal').value),m=Number($('mileage').value),long=Number($('longest').value),days=Number($('days').value),exp=$('experience').value;if(long>m){$('plan').innerHTML='<p class="notice">Your longest recent run exceeds your weekly distance. Check your profile values before generating a plan.</p>';return}try{localStorage.setItem('ultraProfile',JSON.stringify({race:r.id,m,long,days,exp}))}catch{}const weeks=Math.floor((new Date(r.date+'T12:00:00')-new Date())/604800000);const needed=(r.km>=160?28:20)+(exp==='new'?4:0)+(m<30?8:0);const peak=Math.round(Math.max(m,Math.min(m*1.6,exp==='new'?75:r.km>=160?110:90)));const focus=r.terrain==='Forest'?'Build confidence on uneven forest trails and sustained climbs.':'Practise power hiking, controlled descending and race-like elevation.';
let notice=weeks<=0?'This edition has passed. Use this outline for a future edition once its date is confirmed.':weeks<needed?`Only ${weeks} weeks remain; this profile suggests at least ${needed} weeks of preparation. Prioritise a later race or consult a coach rather than compressing the build.`:`${weeks} weeks until the listed date. Use the extra time to build a consistent base before the ${needed}-week outline.`;
$('plan').innerHTML=`<div class="plan"><h3>Your ${needed}-week outline</h3><p><strong>${r.name}</strong> · ${days} days a week · ${exp==='new'?'first ultra':exp==='some'?'ultra experience':'experienced runner'}</p><p class="notice">${notice}${r.id==='uta'?' Date uses the festival start; confirm your race day.':''}</p><table><tr><th>Phase</th><th>Focus</th><th>Weekly km guide</th></tr><tr><td>Base · ${needed-12} weeks</td><td>Consistency and easy effort</td><td>${m}–${Math.min(peak,Math.round(m*1.15))}</td></tr><tr><td>Build · 6 weeks</td><td>Trail endurance and strength</td><td>${Math.min(peak,Math.round(m*1.15))}–${Math.max(m,Math.round(peak*.9))}</td></tr><tr><td>Specific · 3 weeks</td><td>Race terrain and equipment</td><td>Up to ${peak}</td></tr><tr><td>Taper · 3 weeks</td><td>Reduce volume; arrive rested</td><td>~70%, 50%, 30% of peak</td></tr></table><ul><li>${days-2} easy runs, one terrain-focused session and one easy long run per week. Include rest days.</li><li>Start your long run near ${Math.min(long,Math.round(m*.4))} km; extend gradually only when recovering well. Keep most running conversational.</li><li>${focus}</li><li>${r.temp>=25?'Practise your heat and hydration strategy gradually in safe conditions.':'Rehearse clothing and mandatory kit for cold, rain and night conditions.'}</li><li>Practise fuelling during long runs; include strength twice a week and a lighter recovery week every 3–4 weeks.</li></ul><p>These are flexible planning ranges, not compulsory targets. If current mileage is already high, maintain it rather than chasing an increase.</p></div>`};
try{const p=JSON.parse(localStorage.getItem('ultraProfile'));if(p){$('raceGoal').value=p.race;$('mileage').value=p.m;$('longest').value=p.long;$('days').value=p.days;$('experience').value=p.exp}}catch{}
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({researched:'2026-10-13',notes:'Curated static data. Temperature and difficulty are editorial estimates. UTA date is festival start; UTMB is a past edition.',races},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ultra-atlas-races.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};render();
